create table public.competition_action_requests(request_id uuid primary key,action text not null,match_id uuid references public.matches(id) on delete cascade,response jsonb not null,created_at timestamptz not null default now());
create table public.match_snapshots(id uuid primary key default gen_random_uuid(),match_id uuid not null unique references public.matches(id),tournament_id uuid not null references public.tournaments(id),stage_name text not null,stage_type public.competition_stage_type not null,group_name text,round_number integer not null,match_number integer not null,best_of integer not null,team_a_id uuid,team_a_name text,team_a_tag text,team_b_id uuid,team_b_name text,team_b_tag text,team_a_lineup jsonb not null default '[]',team_b_lineup jsonb not null default '[]',team_a_score integer,team_b_score integer,winner_team_id uuid,winner_name text,status public.match_status not null,completed_at timestamptz not null,created_at timestamptz not null default now());
alter table public.competition_action_requests enable row level security;alter table public.match_snapshots enable row level security;
create policy match_snapshot_member_read on public.match_snapshots for select to authenticated using(exists(select 1 from public.tournament_members tm where tm.tournament_id=match_snapshots.tournament_id and tm.user_id=(select auth.uid())and tm.status='active'));
grant select on public.match_snapshots to authenticated;

create function private.snapshot_completed_match()returns trigger language plpgsql security definer set search_path='' as $$begin if new.status in('completed','forfeit')and old.status not in('completed','forfeit')then insert into public.match_snapshots(match_id,tournament_id,stage_name,stage_type,group_name,round_number,match_number,best_of,team_a_id,team_a_name,team_a_tag,team_b_id,team_b_name,team_b_tag,team_a_lineup,team_b_lineup,team_a_score,team_b_score,winner_team_id,winner_name,status,completed_at)select new.id,new.tournament_id,s.name,s.stage_type,g.name,new.round_number,new.match_number,new.best_of,a.id,a.name,a.short_tag,b.id,b.name,b.short_tag,coalesce((select jsonb_agg(jsonb_build_object('player_id',lp.player_id,'ign',lp.player_ign,'substitute',lp.is_substitute)order by lp.player_ign)from public.match_lineups l join public.match_lineup_players lp on lp.lineup_id=l.id where l.match_id=new.id and l.team_id=new.team_a_id),'[]'),coalesce((select jsonb_agg(jsonb_build_object('player_id',lp.player_id,'ign',lp.player_ign,'substitute',lp.is_substitute)order by lp.player_ign)from public.match_lineups l join public.match_lineup_players lp on lp.lineup_id=l.id where l.match_id=new.id and l.team_id=new.team_b_id),'[]'),new.team_a_score,new.team_b_score,new.winner_team_id,w.name,new.status,new.completed_at from public.competition_stages s left join public.competition_groups g on g.id=new.group_id left join public.teams a on a.id=new.team_a_id left join public.teams b on b.id=new.team_b_id left join public.teams w on w.id=new.winner_team_id where s.id=new.stage_id on conflict(match_id)do nothing;end if;return new;end$$;
create trigger snapshot_match_completion after update of status on public.matches for each row execute function private.snapshot_completed_match();

create function private.produce_match_notifications()returns trigger language plpgsql security definer set search_path='' as $$declare v_event text;begin v_event:=case when new.status='awaiting_confirmation'and old.status is distinct from new.status then 'RESULT_AWAITING_CONFIRMATION' when new.status='disputed'and old.status is distinct from new.status then 'RESULT_DISPUTED' when new.status in('completed','forfeit')and old.status not in('completed','forfeit')then 'MATCH_COMPLETED' when new.status='rescheduled'and old.status is distinct from new.status then 'MATCH_RESCHEDULED' end;if v_event is not null then insert into public.competition_notifications(tournament_id,recipient_user_id,event_type,match_id,payload)select new.tournament_id,t.captain_user_id,v_event,new.id,jsonb_build_object('status',new.status)from public.teams t where t.id in(new.team_a_id,new.team_b_id)and not exists(select 1 from public.competition_notifications n where n.match_id=new.id and n.recipient_user_id=t.captain_user_id and n.event_type=v_event and n.payload->>'status'=new.status::text);end if;return new;end$$;
create trigger match_notification_events after update of status on public.matches for each row execute function private.produce_match_notifications();
create function private.notify_match_scheduled()returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.competition_notifications(tournament_id,recipient_user_id,event_type,match_id)select new.tournament_id,captain_user_id,'MATCH_SCHEDULED',new.id from public.teams where id in(new.team_a_id,new.team_b_id);return new;end$$;
create trigger notify_match_scheduled after insert on public.matches for each row execute function private.notify_match_scheduled();

create or replace function public.respond_to_match_result(p_submission_id uuid,p_confirm boolean,p_reason text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare s public.match_result_submissions%rowtype;m public.matches%rowtype;v_team uuid;v_response jsonb;begin select response into v_response from public.competition_action_requests where request_id=p_request_id;if v_response is not null then return v_response;end if;select * into s from public.match_result_submissions where id=p_submission_id for update;select * into m from public.matches where id=s.match_id for update;select id into v_team from public.teams where captain_user_id=(select auth.uid())and tournament_id=m.tournament_id and id in(m.team_a_id,m.team_b_id);if v_team is null or v_team=s.submitting_team_id then raise exception 'NOT_PARTICIPATING_TEAM'using errcode='P0001';end if;if m.status in('completed','forfeit')then if p_confirm then v_response:=jsonb_build_object('code','DUPLICATE_REQUEST');insert into public.competition_action_requests values(p_request_id,'confirm',m.id,v_response,now())on conflict do nothing;return v_response;end if;raise exception 'MATCH_ALREADY_COMPLETED'using errcode='P0001';end if;if m.status='disputed'and p_confirm then raise exception 'MATCH_DISPUTED'using errcode='P0001';end if;if p_confirm then update public.match_result_submissions set status='confirmed'where id=s.id;perform private.complete_match(m.id,s.team_a_score,s.team_b_score);perform private.audit_match(m.id,'RESULT_CONFIRMED');v_response:=jsonb_build_object('code','RESULT_CONFIRMED');else if nullif(trim(p_reason),'')is null then raise exception 'DISPUTE_REASON_REQUIRED'using errcode='P0001';end if;insert into public.match_disputes(match_id,submission_id,opened_by,opening_team_id,reason,request_id)values(m.id,s.id,(select auth.uid()),v_team,p_reason,p_request_id);update public.match_result_submissions set status='disputed'where id=s.id;update public.matches set status='disputed',revision=revision+1 where id=m.id;perform private.audit_match(m.id,'RESULT_DISPUTED');v_response:=jsonb_build_object('code','RESULT_DISPUTED');end if;insert into public.competition_action_requests values(p_request_id,case when p_confirm then 'confirm'else'dispute'end,m.id,v_response,now())on conflict do nothing;return v_response;end$$;

create or replace function public.reschedule_match(p_match_id uuid,p_scheduled_at timestamptz,p_reason text)returns void language plpgsql security definer set search_path='' as $$declare m public.matches%rowtype;begin select * into m from public.matches where id=p_match_id for update;if not private.is_competition_official(m.tournament_id)then raise exception 'UNAUTHORIZED_REFEREE'using errcode='P0001';end if;if m.status in('completed','forfeit','cancelled')then raise exception 'MATCH_ALREADY_COMPLETED'using errcode='P0001';end if;if nullif(trim(p_reason),'')is null then raise exception 'RESCHEDULE_REASON_REQUIRED'using errcode='P0001';end if;insert into public.match_schedule_changes(match_id,old_scheduled_at,new_scheduled_at,reason,changed_by)values(m.id,m.scheduled_at,p_scheduled_at,p_reason,(select auth.uid()));update public.matches set scheduled_at=p_scheduled_at,check_in_opens_at=p_scheduled_at-interval'30 minutes',check_in_deadline=p_scheduled_at+interval'10 minutes',status='rescheduled',revision=revision+1 where id=m.id;perform private.audit_match(m.id,'MATCH_RESCHEDULED',jsonb_build_object('old',m.scheduled_at,'new',p_scheduled_at,'reason',p_reason));end$$;

revoke all on table public.competition_action_requests from public,anon,authenticated;
revoke all on function private.snapshot_completed_match(),private.produce_match_notifications(),private.notify_match_scheduled()from public,anon,authenticated;

alter function public.generate_competition_schedule(uuid,timestamptz,integer)rename to generate_competition_schedule_phase06;
create function private.build_single_elimination(p_tournament_id uuid,p_team_ids uuid[],p_scheduled_start timestamptz,p_interval_minutes integer,p_stage_name text default'Knockout')returns integer language plpgsql security definer set search_path='' as $$declare v_n int:=cardinality(p_team_ids);v_size int:=1;v_rounds int:=0;v_byes int;v_stage uuid;v_slot int;v_round int;v_match int;v_index int:=1;v_id uuid;v_next uuid;v_count int:=0;v_best int;begin if v_n<2 then raise exception 'INSUFFICIENT_TEAMS'using errcode='P0001';end if;while v_size<v_n loop v_size:=v_size*2;v_rounds:=v_rounds+1;end loop;if v_rounds=0 then v_rounds:=1;end if;v_byes:=v_size-v_n;select default_best_of into v_best from public.competition_settings where tournament_id=p_tournament_id;insert into public.competition_stages(tournament_id,name,stage_type,sequence_number)values(p_tournament_id,p_stage_name,'knockout',(select coalesce(max(sequence_number),0)+1 from public.competition_stages where tournament_id=p_tournament_id))returning id into v_stage;
for v_round in 2..v_rounds loop for v_match in 1..(v_size/power(2,v_round))::int loop insert into public.matches(tournament_id,stage_id,round_number,match_number,best_of,scheduled_at)values(p_tournament_id,v_stage,v_round,v_match,v_best,p_scheduled_start+make_interval(mins=>(v_round-1)*p_interval_minutes));v_count:=v_count+1;end loop;end loop;
for v_slot in 1..(v_size/2)loop if v_rounds>1 then select id into v_next from public.matches where stage_id=v_stage and round_number=2 and match_number=ceil(v_slot/2.0);else v_next:=null;end if;if v_slot<=v_byes then update public.matches set team_a_id=case when v_slot%2=1 then p_team_ids[v_index]else team_a_id end,team_b_id=case when v_slot%2=0 then p_team_ids[v_index]else team_b_id end where id=v_next;insert into public.audit_events(tournament_id,actor_user_id,event_type,entity_type,entity_id,payload)values(p_tournament_id,(select auth.uid()),'BRACKET_BYE_ADVANCED','match',v_next,jsonb_build_object('team_id',p_team_ids[v_index],'source_slot',v_slot));v_index:=v_index+1;else insert into public.matches(tournament_id,stage_id,round_number,match_number,team_a_id,team_b_id,best_of,scheduled_at,next_match_id,next_match_slot)values(p_tournament_id,v_stage,1,v_slot,p_team_ids[v_index],p_team_ids[v_index+1],v_best,p_scheduled_start,v_next,case when v_slot%2=1 then 1 else 2 end)returning id into v_id;v_index:=v_index+2;v_count:=v_count+1;end if;end loop;
for v_round in 2..v_rounds-1 loop update public.matches m set next_match_id=n.id,next_match_slot=case when m.match_number%2=1 then 1 else 2 end from public.matches n where m.stage_id=v_stage and n.stage_id=v_stage and m.round_number=v_round and n.round_number=v_round+1 and n.match_number=ceil(m.match_number/2.0);end loop;return v_count;end$$;
create function public.generate_competition_schedule(p_tournament_id uuid,p_scheduled_start timestamptz default null,p_interval_minutes integer default 60)returns integer language plpgsql security definer set search_path='' as $$declare v_format public.competition_format;v_count int;v_teams uuid[];begin if not public.is_tournament_role(p_tournament_id,'organizer')then raise exception 'UNAUTHORIZED_REFEREE'using errcode='P0001';end if;select format into v_format from public.competition_settings where tournament_id=p_tournament_id;if v_format='single_elimination'then if exists(select 1 from public.matches where tournament_id=p_tournament_id)then raise exception 'SCHEDULE_ALREADY_EXISTS'using errcode='P0001';end if;select array_agg(id order by id)into v_teams from public.teams where tournament_id=p_tournament_id;v_count:=private.build_single_elimination(p_tournament_id,v_teams,p_scheduled_start,p_interval_minutes);insert into public.audit_events(tournament_id,actor_user_id,event_type,entity_type,entity_id,payload)values(p_tournament_id,(select auth.uid()),'SCHEDULE_GENERATED','tournament',p_tournament_id,jsonb_build_object('matches',v_count,'format',v_format));return v_count;end if;return public.generate_competition_schedule_phase06(p_tournament_id,p_scheduled_start,p_interval_minutes);end$$;
revoke all on function public.generate_competition_schedule_phase06(uuid,timestamptz,integer),private.build_single_elimination(uuid,uuid[],timestamptz,integer,text)from public,anon,authenticated;revoke all on function public.generate_competition_schedule(uuid,timestamptz,integer)from public,anon;grant execute on function public.generate_competition_schedule(uuid,timestamptz,integer)to authenticated;

create view public.public_competition_rankings with(security_barrier=true)as with base as(select s.*,c.tiebreak_rules,c.points_win,c.points_loss from public.public_standings s join public.competition_settings c on c.tournament_id=s.tournament_id),metrics as(select b.*,coalesce((select sum(case when m.winner_team_id=b.team_id then b.points_win else b.points_loss end)from public.matches m join base opponent on opponent.tournament_id=b.tournament_id and opponent.group_id is not distinct from b.group_id and opponent.points=b.points and opponent.team_id<>b.team_id and opponent.team_id in(m.team_a_id,m.team_b_id)where m.tournament_id=b.tournament_id and m.group_id is not distinct from b.group_id and b.team_id in(m.team_a_id,m.team_b_id)and m.status in('completed','forfeit')),0)head_to_head_points from base b),keyed as(select m.*,array(select-case rule when'points'then m.points when'head_to_head'then m.head_to_head_points when'game_difference'then m.game_difference when'games_won'then m.games_won when'wins'then m.wins else 0 end from jsonb_array_elements_text(m.tiebreak_rules)with ordinality r(rule,ord)order by ord)::bigint[] sort_key from metrics m)select team_id,tournament_id,team_name,short_tag,group_id,played,wins,losses,games_won,games_lost,game_difference,points,head_to_head_points,sort_key,row_number()over(partition by tournament_id,group_id order by sort_key desc,team_name)position,count(*)over(partition by tournament_id,group_id,sort_key)>1 tiebreak_required from keyed;
grant select on public.public_competition_rankings to anon,authenticated;
create table public.group_advancement_results(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id),group_id uuid not null references public.competition_groups(id),team_id uuid not null references public.teams(id),group_position integer not null,knockout_seed integer not null,created_at timestamptz not null default now(),unique(tournament_id,team_id),unique(tournament_id,knockout_seed));
alter table public.group_advancement_results enable row level security;create policy advancement_member_read on public.group_advancement_results for select to authenticated using(exists(select 1 from public.tournament_members tm where tm.tournament_id=group_advancement_results.tournament_id and tm.user_id=(select auth.uid())and tm.status='active'));grant select on public.group_advancement_results to authenticated;
create view public.public_group_advancements with(security_barrier=true)as select a.tournament_id,a.group_id,g.name group_name,a.team_id,t.name team_name,t.short_tag,a.group_position,a.knockout_seed,a.created_at from public.group_advancement_results a join public.competition_groups g on g.id=a.group_id join public.teams t on t.id=a.team_id;grant select on public.public_group_advancements to anon,authenticated;
create function public.advance_groups_to_knockout(p_tournament_id uuid,p_scheduled_start timestamptz default null,p_interval_minutes integer default 60)returns integer language plpgsql security definer set search_path='' as $$declare v_top int;v_qualifiers uuid[];v_count int;v_boundary bigint[];g record;begin if not public.is_tournament_role(p_tournament_id,'organizer')then raise exception 'UNAUTHORIZED_REFEREE'using errcode='P0001';end if;if exists(select 1 from public.group_advancement_results where tournament_id=p_tournament_id)then return(select count(*)::int from public.group_advancement_results where tournament_id=p_tournament_id);end if;if exists(select 1 from public.matches where tournament_id=p_tournament_id and group_id is not null and status not in('completed','forfeit'))then raise exception 'GROUP_STAGE_INCOMPLETE'using errcode='P0001';end if;select advance_per_group into v_top from public.competition_settings where tournament_id=p_tournament_id;for g in select id from public.competition_groups where tournament_id=p_tournament_id order by sequence_number loop select sort_key into v_boundary from public.public_competition_rankings where group_id=g.id order by position offset v_top-1 limit 1;if v_boundary is null or exists(select 1 from public.public_competition_rankings where group_id=g.id and sort_key=v_boundary and position>v_top)then raise exception 'TIEBREAK_REQUIRED'using errcode='P0001';end if;end loop;
insert into public.group_advancement_results(tournament_id,group_id,team_id,group_position,knockout_seed)select p_tournament_id,r.group_id,r.team_id,r.position,row_number()over(order by r.position,g.sequence_number)::int from public.public_competition_rankings r join public.competition_groups g on g.id=r.group_id where r.tournament_id=p_tournament_id and r.position<=v_top order by r.position,g.sequence_number;select array_agg(team_id order by knockout_seed)into v_qualifiers from public.group_advancement_results where tournament_id=p_tournament_id;v_count:=private.build_single_elimination(p_tournament_id,v_qualifiers,p_scheduled_start,p_interval_minutes,'Group Knockout');insert into public.audit_events(tournament_id,actor_user_id,event_type,entity_type,entity_id,payload)values(p_tournament_id,(select auth.uid()),'GROUP_ADVANCEMENT_CONFIRMED','tournament',p_tournament_id,jsonb_build_object('qualifiers',v_qualifiers,'matches',v_count));return cardinality(v_qualifiers);end$$;
revoke all on function public.advance_groups_to_knockout(uuid,timestamptz,integer)from public,anon;grant execute on function public.advance_groups_to_knockout(uuid,timestamptz,integer)to authenticated;

create or replace function public.submit_match_result(p_match_id uuid,p_team_a_score integer,p_team_b_score integer,p_evidence_path text,p_notes text,p_request_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare m public.matches%rowtype;v_team uuid;v_winner uuid;v_id uuid;v_a int;v_b int;prior public.match_result_submissions%rowtype;begin select id into v_id from public.match_result_submissions where request_id=p_request_id;if v_id is not null then return jsonb_build_object('id',v_id,'code','DUPLICATE_REQUEST');end if;select * into m from public.matches where id=p_match_id for update;if m.status in('completed','forfeit','cancelled')then raise exception 'MATCH_ALREADY_COMPLETED'using errcode='P0001';end if;select id into v_team from public.teams where tournament_id=m.tournament_id and captain_user_id=(select auth.uid())and id in(m.team_a_id,m.team_b_id);if v_team is null then raise exception 'NOT_PARTICIPATING_TEAM'using errcode='P0001';end if;if v_team=m.team_b_id then v_a:=p_team_b_score;v_b:=p_team_a_score;else v_a:=p_team_a_score;v_b:=p_team_b_score;end if;v_winner:=private.validate_match_score(m,v_a,v_b);insert into public.match_result_submissions(match_id,submitting_team_id,submitted_by,team_a_score,team_b_score,winner_team_id,evidence_path,notes,request_id)values(p_match_id,v_team,(select auth.uid()),v_a,v_b,v_winner,p_evidence_path,p_notes,p_request_id)returning id into v_id;select * into prior from public.match_result_submissions where match_id=p_match_id and submitting_team_id<>v_team order by created_at limit 1;if prior.id is null then update public.matches set status='awaiting_confirmation',revision=revision+1 where id=p_match_id;perform private.audit_match(p_match_id,'RESULT_SUBMITTED',jsonb_build_object('submission_id',v_id));return jsonb_build_object('id',v_id,'code','RESULT_SUBMITTED');elsif prior.team_a_score=v_a and prior.team_b_score=v_b then update public.match_result_submissions set status='confirmed'where match_id=p_match_id;perform private.complete_match(p_match_id,v_a,v_b);perform private.audit_match(p_match_id,'RESULT_CONFIRMED',jsonb_build_object('agreement','dual_submission'));return jsonb_build_object('id',v_id,'code','RESULT_CONFIRMED');else update public.match_result_submissions set status='disputed'where match_id=p_match_id;insert into public.match_disputes(match_id,submission_id,opened_by,opening_team_id,reason,request_id)values(p_match_id,v_id,(select auth.uid()),v_team,'Conflicting team result submissions',p_request_id);update public.matches set status='disputed',revision=revision+1 where id=p_match_id;perform private.audit_match(p_match_id,'RESULT_DISPUTED',jsonb_build_object('conflict','dual_submission'));return jsonb_build_object('id',v_id,'code','RESULT_DISPUTED');end if;exception when unique_violation then select id into v_id from public.match_result_submissions where request_id=p_request_id;if v_id is not null then return jsonb_build_object('id',v_id,'code','DUPLICATE_REQUEST');end if;raise exception 'RESULT_ALREADY_SUBMITTED'using errcode='P0001';end$$;
alter publication supabase_realtime add table public.match_lineups,public.competition_notifications,public.group_advancement_results,public.match_snapshots;
create unique index competition_notification_due_once on public.competition_notifications(match_id,recipient_user_id,event_type)where event_type in('CHECKIN_OPEN','CHECKIN_DEADLINE_APPROACHING');
create function private.emit_due_match_notifications()returns integer language plpgsql security definer set search_path='' as $$declare v_count int;begin insert into public.competition_notifications(tournament_id,recipient_user_id,event_type,match_id)select m.tournament_id,t.captain_user_id,e.event_type,m.id from public.matches m join public.teams t on t.id in(m.team_a_id,m.team_b_id)cross join lateral(values('CHECKIN_OPEN',m.check_in_opens_at),('CHECKIN_DEADLINE_APPROACHING',m.check_in_deadline-interval'10 minutes'))e(event_type,due_at)where m.status in('scheduled','check_in','rescheduled')and e.due_at is not null and clock_timestamp()>=e.due_at on conflict do nothing;get diagnostics v_count=row_count;return v_count;end$$;
revoke all on function private.emit_due_match_notifications()from public,anon,authenticated;
select cron.schedule('draftgg-match-notifications','* * * * *',$$select private.emit_due_match_notifications()$$)where not exists(select 1 from cron.job where jobname='draftgg-match-notifications');
create function private.refresh_match_readiness()returns trigger language plpgsql security definer set search_path='' as $$declare v_match uuid;begin v_match:=new.match_id;update public.matches m set status='ready',revision=revision+1 where m.id=v_match and m.status in('scheduled','check_in','rescheduled')and(select count(*)from public.match_check_ins where match_id=v_match)=2 and(select count(*)from public.match_lineups where match_id=v_match)=2;return new;end$$;
create trigger checkin_refresh_readiness after insert on public.match_check_ins for each row execute function private.refresh_match_readiness();create trigger lineup_refresh_readiness after insert on public.match_lineups for each row execute function private.refresh_match_readiness();
create function private.lock_lineups_on_start()returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='live'and old.status is distinct from new.status then update public.match_lineups set locked_at=clock_timestamp()where match_id=new.id and locked_at is null;end if;return new;end$$;
create trigger lock_lineups_when_live after update of status on public.matches for each row execute function private.lock_lineups_on_start();
create function private.notify_dispute_resolution()returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='resolved'and old.status='open'then insert into public.competition_notifications(tournament_id,recipient_user_id,event_type,match_id)select m.tournament_id,t.captain_user_id,'DISPUTE_RESOLVED',m.id from public.matches m join public.teams t on t.id in(m.team_a_id,m.team_b_id)where m.id=new.match_id;end if;return new;end$$;
create trigger dispute_resolution_notifications after update of status on public.match_disputes for each row execute function private.notify_dispute_resolution();
revoke all on function private.refresh_match_readiness(),private.lock_lineups_on_start(),private.notify_dispute_resolution()from public,anon,authenticated;
create function private.broadcast_public_match_update()returns trigger language plpgsql security definer set search_path='' as $$begin perform realtime.send(jsonb_build_object('match_id',new.id,'status',new.status,'team_a_score',new.team_a_score,'team_b_score',new.team_b_score,'winner_team_id',new.winner_team_id,'scheduled_at',new.scheduled_at,'revision',new.revision),'match_update','tournament:'||new.tournament_id::text,false);return new;end$$;
create trigger broadcast_safe_match_update after insert or update of status,team_a_score,team_b_score,winner_team_id,scheduled_at,revision on public.matches for each row execute function private.broadcast_public_match_update();
revoke all on function private.broadcast_public_match_update()from public,anon,authenticated;
create or replace view public.public_competition_rankings with(security_barrier=true)as with base as(select s.*,c.tiebreak_rules,c.points_win,c.points_loss from public.public_standings s join public.competition_settings c on c.tournament_id=s.tournament_id),metrics as(select b.*,coalesce((select sum(case when m.winner_team_id=b.team_id then b.points_win else b.points_loss end)from public.matches m join base opponent on opponent.tournament_id=b.tournament_id and opponent.group_id is not distinct from b.group_id and opponent.points=b.points and opponent.team_id<>b.team_id and opponent.team_id in(m.team_a_id,m.team_b_id)where m.tournament_id=b.tournament_id and m.group_id is not distinct from b.group_id and b.team_id in(m.team_a_id,m.team_b_id)and m.status in('completed','forfeit')),0)head_to_head_points from base b),keyed as(select m.*,array(select case rule when'points'then m.points when'head_to_head'then m.head_to_head_points when'game_difference'then m.game_difference when'games_won'then m.games_won when'wins'then m.wins else 0 end from jsonb_array_elements_text(m.tiebreak_rules)with ordinality r(rule,ord)order by ord)::bigint[] sort_key from metrics m)select team_id,tournament_id,team_name,short_tag,group_id,played,wins,losses,games_won,games_lost,game_difference,points,head_to_head_points,sort_key,row_number()over(partition by tournament_id,group_id order by sort_key desc,team_name)position,count(*)over(partition by tournament_id,group_id,sort_key)>1 tiebreak_required from keyed;
create or replace function public.advance_groups_to_knockout(p_tournament_id uuid,p_scheduled_start timestamptz default null,p_interval_minutes integer default 60)returns integer language plpgsql security definer set search_path='' as $$declare v_top int;v_qualifiers uuid[];v_count int;v_boundary bigint[];grp record;begin if not public.is_tournament_role(p_tournament_id,'organizer')then raise exception 'UNAUTHORIZED_REFEREE'using errcode='P0001';end if;if exists(select 1 from public.group_advancement_results where tournament_id=p_tournament_id)then return(select count(*)::int from public.group_advancement_results where tournament_id=p_tournament_id);end if;if exists(select 1 from public.matches where tournament_id=p_tournament_id and group_id is not null and status not in('completed','forfeit'))then raise exception 'GROUP_STAGE_INCOMPLETE'using errcode='P0001';end if;select advance_per_group into v_top from public.competition_settings where tournament_id=p_tournament_id;for grp in select cg.id from public.competition_groups cg where cg.tournament_id=p_tournament_id order by cg.sequence_number loop select sort_key into v_boundary from public.public_competition_rankings where group_id=grp.id order by position offset v_top-1 limit 1;if v_boundary is null or exists(select 1 from public.public_competition_rankings where group_id=grp.id and sort_key=v_boundary and position>v_top)then raise exception 'TIEBREAK_REQUIRED'using errcode='P0001';end if;end loop;insert into public.group_advancement_results(tournament_id,group_id,team_id,group_position,knockout_seed)select p_tournament_id,r.group_id,r.team_id,r.position,row_number()over(order by r.position,cg.sequence_number)::int from public.public_competition_rankings r join public.competition_groups cg on cg.id=r.group_id where r.tournament_id=p_tournament_id and r.position<=v_top order by r.position,cg.sequence_number;select array_agg(team_id order by knockout_seed)into v_qualifiers from public.group_advancement_results where tournament_id=p_tournament_id;v_count:=private.build_single_elimination(p_tournament_id,v_qualifiers,p_scheduled_start,p_interval_minutes,'Group Knockout');insert into public.audit_events(tournament_id,actor_user_id,event_type,entity_type,entity_id,payload)values(p_tournament_id,(select auth.uid()),'GROUP_ADVANCEMENT_CONFIRMED','tournament',p_tournament_id,jsonb_build_object('qualifiers',v_qualifiers,'matches',v_count));return cardinality(v_qualifiers);end$$;

create or replace function public.complete_competition(p_tournament_id uuid)returns uuid language plpgsql security definer set search_path='' as $$declare v_format public.competition_format;v_champion uuid;v_runner uuid;v_final public.matches%rowtype;begin if not public.is_tournament_role(p_tournament_id,'organizer')then raise exception 'UNAUTHORIZED_REFEREE'using errcode='P0001';end if;select format into v_format from public.competition_settings where tournament_id=p_tournament_id;if v_format is null then raise exception 'COMPETITION_NOT_CONFIGURED'using errcode='P0001';end if;if exists(select 1 from public.matches where tournament_id=p_tournament_id and status not in('completed','forfeit','cancelled'))or exists(select 1 from public.match_disputes d join public.matches m on m.id=d.match_id where m.tournament_id=p_tournament_id and d.status='open')then raise exception 'COMPETITION_INCOMPLETE'using errcode='P0001';end if;if v_format='groups'and exists(select 1 from public.public_competition_rankings where tournament_id=p_tournament_id and tiebreak_required)then raise exception 'TIEBREAK_REQUIRED'using errcode='P0001';end if;if v_format in('single_elimination','groups')and exists(select 1 from public.competition_stages where tournament_id=p_tournament_id and stage_type='knockout')then select * into v_final from public.matches where tournament_id=p_tournament_id and stage_id=(select id from public.competition_stages where tournament_id=p_tournament_id and stage_type='knockout'order by sequence_number desc limit 1)and next_match_id is null order by round_number desc,match_number desc limit 1;if v_final.id is null or v_final.status not in('completed','forfeit')or v_final.winner_team_id is null then raise exception 'COMPETITION_INCOMPLETE'using errcode='P0001';end if;v_champion:=v_final.winner_team_id;v_runner:=v_final.loser_team_id;else select team_id into v_champion from public.public_competition_rankings where tournament_id=p_tournament_id order by group_id nulls first,position limit 1;select team_id into v_runner from public.public_competition_rankings where tournament_id=p_tournament_id order by group_id nulls first,position offset 1 limit 1;end if;if v_champion is null then raise exception 'COMPETITION_INCOMPLETE'using errcode='P0001';end if;insert into public.competition_result_snapshots(tournament_id,champion_team_id,runner_up_team_id,settings,standings,matches)select p_tournament_id,v_champion,v_runner,to_jsonb(s),coalesce((select jsonb_agg(to_jsonb(x)order by group_id,position)from public.public_competition_rankings x where x.tournament_id=p_tournament_id),'[]'),coalesce((select jsonb_agg(to_jsonb(x)order by round_number,match_number)from public.public_matches x where x.tournament_id=p_tournament_id),'[]')from public.competition_settings s where s.tournament_id=p_tournament_id on conflict(tournament_id)do nothing;update public.tournaments set status='completed'where id=p_tournament_id;insert into public.audit_events(tournament_id,actor_user_id,event_type,entity_type,entity_id,payload)values(p_tournament_id,(select auth.uid()),'COMPETITION_COMPLETED','tournament',p_tournament_id,jsonb_build_object('champion_team_id',v_champion,'runner_up_team_id',v_runner))on conflict do nothing;return p_tournament_id;end$$;
